css:
/* Слайдер «до и после». Цвета берутся из токенов дизайн-системы, в скобках — запасные.
   Граница двигается только через clip-path (слой «до») и transform (линия) — вёрстка не пересчитывается. */
.ba { --pos: 50%; margin: 0; }
.ba__stage {
  position: relative; overflow: hidden; isolation: isolate;
  aspect-ratio: var(--ba-ratio, 3 / 2);
  border-radius: var(--radius-lg, 20px);
  background: var(--color-surface, #eef0f3);
  touch-action: pan-y; /* вертикальный жест листает страницу, горизонтальный двигает линию */
  touch-action: pan-y pinch-zoom; /* и щипок увеличивает снимок; где значение не знают, остаётся строка выше */
  -webkit-user-select: none; user-select: none; -webkit-tap-highlight-color: transparent;
}
/* Курсор и отклик ручки — только когда скрипт ожил (класс is-on): без JS это неподвижная картинка 50 на 50 */
.ba.is-on .ba__stage { cursor: ew-resize; }
.ba__img, .ba__before { position: absolute; inset: 0; }
.ba__img { width: 100%; height: 100%; object-fit: cover; pointer-events: none; }
.ba__before {
  clip-path: inset(0 calc(100% - var(--pos)) 0 0); /* видна левая часть снимка «до» шириной --pos */
  transition: clip-path 160ms cubic-bezier(.2, 0, 0, 1);
}
.ba__divider {
  position: absolute; inset: 0; pointer-events: none;
  transform: translate3d(var(--pos), 0, 0); /* проценты transform — от своей ширины, а она равна ширине кадра */
  transition: transform 160ms cubic-bezier(.2, 0, 0, 1);
}
/* Во время перетаскивания линия идёт за пальцем 1:1, без догоняющего сглаживания */
.ba.is-dragging .ba__before, .ba.is-dragging .ba__divider { transition: none; }
.ba__divider::before {
  content: ""; position: absolute; top: 0; bottom: 0; left: -1px; width: 2px;
  background: var(--ba-line, #ffffff); box-shadow: 0 0 0 1px rgba(0, 0, 0, .28);
}
.ba__knob {
  position: absolute; left: -22px; top: 50%; width: 44px; height: 44px; margin-top: -22px;
  display: grid; place-items: center; border-radius: 50%;
  background: var(--color-surface, #ffffff); color: var(--color-text, #14161a);
  box-shadow: 0 6px 18px -6px rgba(15, 23, 42, .55);
  transition: transform 120ms cubic-bezier(.2, 0, 0, 1);
}
.ba__knob svg { width: 22px; height: 22px; }
@media (hover: hover) and (pointer: fine) { .ba.is-on .ba__stage:hover .ba__knob { transform: scale(1.06); } }
.ba.is-dragging .ba__knob { transform: scale(1.12); }
/* Родной ползунок: невидим и не ловит мышь, но даёт клавиатуру, фокус и роль slider для экранного диктора */
.ba__range {
  position: absolute; inset: 0; width: 100%; height: 100%; margin: 0;
  opacity: 0; pointer-events: none; -webkit-appearance: none; appearance: none;
}
/* Фокус с клавиатуры — двухцветное кольцо на ручке: видно и на светлом, и на тёмном снимке */
.ba__range:focus-visible ~ .ba__divider .ba__knob {
  outline: 3px solid var(--ba-focus, #14161a); outline-offset: 3px;
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 9px #ffffff;
}
.ba__tag {
  position: absolute; top: 12px; padding: 6px 10px; border-radius: 999px;
  background: rgba(17, 20, 24, .78); color: #ffffff; /* контраст не ниже 9:1 на любом снимке */
  font-size: 13px; font-weight: 600; line-height: 1; letter-spacing: .02em; pointer-events: none;
}
.ba__tag--before { left: 12px; }
.ba__tag--after { right: 12px; }
.ba__caption { margin-top: 12px; color: var(--color-text-muted, #4a5160); font-size: 15px; line-height: 1.5; }
/* Режим высокой контрастности Windows: системные цвета, иначе линия пропадёт на снимке */
@media (forced-colors: active) {
  .ba__divider::before { forced-color-adjust: none; background: CanvasText; }
  .ba__knob { border: 2px solid CanvasText; }
}
/* Уменьшить движение: подсказки-проезда нет (её не запускает скрипт), граница переставляется мгновенно,
   ручка не увеличивается. Перетаскивание остаётся — его ведёт сам человек. Кольцо фокуса остаётся. */
@media (prefers-reduced-motion: reduce) {
  .ba__before, .ba__divider { transition: none; }
  .ba__knob { transform: none !important; transition: none; }
}

js:
// Слайдер «до и после» (в конце <body> или с defer). Мышь и перо двигают линию сразу, палец — только
// горизонтальным жестом (вертикальный листает страницу), касание переставляет линию. Клавиатура и диктор —
// родной input range. Подсказка-проезд — один раз, когда слайдер в кадре и снимки готовы.
(() => {
  const RM = matchMedia('(prefers-reduced-motion: reduce)'), EASE = 'cubic-bezier(.4, 0, .2, 1)', hints = new Map(), stops = [];
  const io = 'IntersectionObserver' in window && new IntersectionObserver((es) => es.forEach((e) => {
    if (e.isIntersecting) { io.unobserve(e.target); setTimeout(hints.get(e.target), 400); }
  }), { threshold: 0.6 });
  document.querySelectorAll('[data-ba]:not(.is-on)').forEach((box) => { // :not(.is-on) — повторный запуск не удвоит обработчики
    const [stage, before, range, line] = ['stage', 'before', 'range', 'divider'].map((c) => box.querySelector('.ba__' + c));
    let anims = [], touched = false, down = null;
    const stop = () => { anims.forEach((a) => a.cancel()); anims = []; };
    const set = (v) => { v = Math.min(100, Math.max(0, v)); const r = Math.round(v); range.value = r; // линия — без округления, ползунок — целые %
      box.style.setProperty('--pos', v.toFixed(2) + '%'); range.setAttribute('aria-valuetext', `До — ${r} %, после — ${100 - r} %`); };
    const at = (e) => set(((e.clientX - down.r.left) / down.r.width) * 100); // рамку меряем один раз за жест
    const own = (e) => down && e.pointerId === down.id, end = (e) => { if (own(e)) { down = null; box.classList.remove('is-dragging'); } };
    stage.addEventListener('pointerdown', (e) => {
      if (!e.isPrimary || e.button !== 0) return;
      touched = true; stop(); stage.setPointerCapture(e.pointerId);
      down = { id: e.pointerId, x: e.clientX, r: stage.getBoundingClientRect(), drag: e.pointerType !== 'touch' };
      if (down.drag) { box.classList.add('is-dragging'); at(e); }
    });
    stage.addEventListener('pointermove', (e) => { if (!own(e)) return; // второй палец или мышь не перехватывают жест
      if (!down.drag && Math.abs(e.clientX - down.x) > 6) { down.drag = true; box.classList.add('is-dragging'); }
      if (down.drag) at(e);
    });
    stage.addEventListener('pointerup', (e) => { if (own(e) && !down.drag) at(e); end(e); }); // касание без сдвига
    stage.addEventListener('pointercancel', end); // браузер забрал жест под прокрутку или масштаб страницы
    range.addEventListener('input', () => { touched = true; stop(); set(+range.value); });
    range.disabled = false; box.classList.add('is-on'); set(+range.value); stops.push(stop); if (io) io.observe(box);
    hints.set(box, () => Promise.all([...box.querySelectorAll('img')].map((i) => i.decode().catch(() => {}))).then(() => {
      if (touched || RM.matches || !before.animate) return; // человек уже двигал сам или просил меньше движения
      const c = +range.value, P = [c, Math.min(c + 22, 95), Math.max(c - 22, 5), c];
      const kf = (f) => P.map((p, i) => ({ offset: [0, 0.3, 0.7, 1][i], easing: EASE, ...f(p) }));
      anims = [before.animate(kf((p) => ({ clipPath: `inset(0 ${100 - p}% 0 0)` })), 1800),
        line.animate(kf((p) => ({ transform: `translate3d(${p}%, 0, 0)` })), 1800)];
    }));
  });
  RM.addEventListener('change', () => { if (RM.matches) stops.forEach((s) => s()); });
})();
